/**
 * Method and sandbox-helper discovery for `query_sdk` / `run_sdk`. Match order:
 * exact path drill-down → namespace prefix listing → substring on path +
 * summary. Client method visibility matches the sandbox dispatch manifests.
 */

import { type Static, Type } from "@sinclair/typebox";
import {
	resolveActingPrincipal,
	resolveWriteEffect,
} from "../authz/entity-policy";
import type { WriteAction } from "../authz/write-action-manifest";
import { resolveMaxAccessLevel } from "../auth/tool-access";
import { getDb } from "../db/client";
import type { Env } from "../index";
import {
	METHOD_METADATA,
	RUNTIME_HELPER_METADATA,
	type MethodMetadata,
} from "../sandbox/method-metadata";
import { SDK_FIELD_ALIASES } from "../sandbox/sdk-aliases";
import {
	sdkMethodVisible,
	type SdkDiscoveryMode,
} from "../sandbox/sdk-method-access";
import type { ToolContext } from "./registry";
import { withValidatedArgs } from "./validate-args";
import { searchLiveConnectors } from "./connector-discovery";

/**
 * agents.* paths → agent_config action that must not be blanket-denied for the
 * method to appear in discovery. list/get use read; mutate uses create/update/
 * delete. setSystemAgent is treated as update. manage is raw — hide when every
 * agent_config action is denied at the blanket.
 */
export const AGENTS_SDK_ACTION: Record<string, WriteAction | "any"> = {
	"agents.list": "read",
	"agents.get": "read",
	"agents.create": "create",
	"agents.update": "update",
	"agents.delete": "delete",
	"agents.setSystemAgent": "update",
	"agents.manage": "any",
};

const SDK_DISCOVERY_METADATA: Record<string, MethodMetadata> = {
	...METHOD_METADATA,
	...RUNTIME_HELPER_METADATA,
};

const NAMESPACES = [
	...new Set(
		Object.keys(SDK_DISCOVERY_METADATA)
			.filter((path) => path.includes("."))
			.map((path) => path.split(".")[0])
	),
].sort();

const METADATA_BY_LOWER_PATH = new Map(
	Object.entries(SDK_DISCOVERY_METADATA).map(([path, meta]) => [
		path.toLowerCase(),
		[path, meta] as const,
	])
);

export const SdkSearchSchema = Type.Object({
	query: Type.String({
		description: `SDK method or runtime-helper discovery query. Use a namespace (e.g. 'behaviors'), one or more dotted paths separated by whitespace (e.g. 'behaviors.create ctx.sleep'), an optional client. prefix, or free text. Pass mode='read' for query_sdk-safe methods only; omit mode for your full run_sdk tier. Namespaces: ${NAMESPACES.join(", ")}.`,
		minLength: 1,
	}),
	mode: Type.Optional(
		Type.Union(
			[
				Type.Literal("read", {
					description: "Only methods callable via query_sdk (read access).",
				}),
				Type.Literal("full", {
					description:
						"Methods callable via run_sdk at your access tier (default).",
				}),
			],
			{
				description:
					"Filter results to match query_sdk ('read') or run_sdk ('full', default).",
			}
		)
	),
	limit: Type.Optional(
		Type.Number({
			description: "Max matches to return. Default 20, max 100.",
			minimum: 1,
			maximum: 100,
		})
	),
});

type SdkSearchArgs = Static<typeof SdkSearchSchema>;

export const SdkSearchResultSchema = Type.Object({
	query: Type.String({ description: "The query that was searched." }),
	match_count: Type.Integer({
		description: "Number of matches returned.",
	}),
	results: Type.Array(Type.String(), {
		description: "Rendered method-documentation strings, one per match.",
	}),
	notes: Type.Optional(
		Type.String({
			description:
				"Free-text hints (e.g. ambiguity, suggestions) when relevant.",
		})
	),
});

export type SdkSearchResult = Static<typeof SdkSearchResultSchema>;

async function agentConfigBlanketDenied(
	ctx: ToolContext,
	action: WriteAction
): Promise<boolean> {
	if (!ctx.organizationId || (!ctx.agentId && !ctx.actingWatcherId)) {
		return false;
	}
	const actor = await resolveActingPrincipal(getDb(), {
		organizationId: ctx.organizationId,
		userId: ctx.userId,
		agentId: ctx.agentId,
		sessionWatcherId: ctx.actingWatcherId ?? null,
	});
	if (actor.kind === "user") return false;
	const effect = await resolveWriteEffect({
		organizationId: ctx.organizationId,
		resourceClass: "agent_config",
		principalKind: actor.kind,
		principalId: actor.id,
		ownerAgentId: actor.ownerAgentId,
		ownerResolved: actor.ownerResolved,
		action,
		targetAgentId: null,
	});
	return effect === "deny" || effect === "disabled";
}

/** Paths hidden for this agent principal by agent_config blanket policy. */
async function deniedAgentsSdkPaths(ctx: ToolContext): Promise<Set<string>> {
	const denied = new Set<string>();
	if (!ctx.agentId && !ctx.actingWatcherId) return denied;

	const actions: WriteAction[] = ["read", "create", "update", "delete"];
	const denyByAction = new Map<WriteAction, boolean>();
	for (const action of actions) {
		denyByAction.set(action, await agentConfigBlanketDenied(ctx, action));
	}
	const allDenied = actions.every((a) => denyByAction.get(a));

	for (const [path, mapped] of Object.entries(AGENTS_SDK_ACTION)) {
		if (mapped === "any") {
			if (allDenied) denied.add(path);
			continue;
		}
		if (denyByAction.get(mapped)) denied.add(path);
	}
	return denied;
}

async function catalogForCaller(
	ctx: ToolContext,
	mode: SdkDiscoveryMode
): Promise<Array<[string, MethodMetadata]>> {
	const callerMax = resolveMaxAccessLevel(ctx.memberRole, ctx.scopes);
	const policyDenied = await deniedAgentsSdkPaths(ctx);
	return Object.entries(SDK_DISCOVERY_METADATA).filter(([path, meta]) => {
		if (!sdkMethodVisible(meta.access, callerMax, mode)) return false;
		if (policyDenied.has(path)) return false;
		return true;
	});
}

function hiddenMethodNote(
	path: string,
	meta: MethodMetadata,
	mode: SdkDiscoveryMode,
	policyDenied: Set<string>
): string {
	if (policyDenied.has(path)) {
		return `${path} is blocked by this agent's agent_config permissions.`;
	}
	if (mode === "read" && meta.access !== "read") {
		return `${path} exists but requires run_sdk (access: ${meta.access}). Retry with mode='full' or call via run_sdk.`;
	}
	if (meta.access === "admin") {
		return `${path} requires workspace admin/owner + mcp:admin.`;
	}
	return `${path} is not available at your access tier (access: ${meta.access}).`;
}

function renderListLine(path: string, meta: MethodMetadata): string {
	return `${path} — ${meta.summary}`;
}

function renderDrillDown(path: string, meta: MethodMetadata): string {
	const lines: string[] = [];
	lines.push(path);
	lines.push(`  ${meta.summary}`);
	lines.push(
		`  access: ${meta.access}${meta.cost ? ` (cost: ${meta.cost})` : ""}`
	);
	if (meta.signature) {
		lines.push(`  signature: ${meta.signature}`);
	}
	// Rendered from the SAME registry the sandbox dispatch rewrites at runtime
	// (sdk-aliases.ts), so documente…1071 tokens truncated….summary &&
		typeof result.summary === "object" &&
		!Array.isArray(result.summary)
			? (result.summary as Record<string, unknown>)
			: null;
	const allAggregateItemsFailed =
		typeof summary?.failed === "number" &&
		summary.failed > 0 &&
		summary.successful === 0;
	// Some mutation policies return `success:false` while durably queueing an
	// approval. That is a non-terminal accepted outcome, not a business failure;
	// callers need its approval URL/run id to continue the workflow.
	const acceptedForApproval = result.approval_queued === true;
	const reportsFailure =
		!acceptedForApproval &&
		(result.success === false ||
			result.ok === false ||
			result.status === "failed" ||
			result.status === "error" ||
			result.status === "timeout" ||
			allAggregateItemsFailed);
	if (!hasError && !reportsFailure) return null;
	const failedItem = Array.isArray(result.results)
		? result.results.find(
				(item): item is Record<string, unknown> =>
					item !== null &&
					typeof item === "object" &&
					!Array.isArray(item) &&
					(item as Record<string, unknown>).success === false,
			)
		: undefined;

	const candidates = [
		result.error,
		result.error_message,
		result.message,
		result.reason,
		failedItem?.error,
		failedItem?.error_message,
		failedItem?.message,
		failedItem?.reason,
	];
	const message = candidates.find(
		(candidate): candidate is string =>
			typeof candidate === "string" && candidate.trim().length > 0,
	);
	return {
		message: message?.trim() ?? `ClientSDK action '${actionName}' failed`,
		result,
	};
}

/** `generate_embeddings` → `generateEmbeddings`; leaves already-camel/plain names intact. */
function snakeToCamel(name: string): string {
	return name.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase());
}

/**
 * Rewrite a leaked internal tool name in a validation error to the public SDK
 * method the caller actually invoked. An arg-validation failure raised deep in
 * an admin handler reads `Invalid arguments for manage_feeds: …`, but a fresh
 * agent only ever called `client.feeds.get` — `manage_feeds` is internal
 * plumbing it cannot search or recover against. When the namespace is known,
 * swap `manage_<x>` for `client.<namespace>.<method>` and keep the field-level
 * detail (`/feed_id: Expected required property`) intact.
 */
function rewriteInternalToolName(
	err: unknown,
	sdkNamespace: string | undefined,
	publicMethod: string,
): unknown {
	if (!sdkNamespace || !(err instanceof ToolUserError)) return err;
	const rewritten = err.message
		.replace(
			/Invalid arguments for manage_[a-z_]+/,
			`Invalid arguments for client.${sdkNamespace}.${publicMethod}`,
		)
		// The valid-args list is scoped to the INTERNAL action (`for action
		// 'read_feed'`) — drop that fragment once the public method already names
		// the call, so no internal action name survives in the message.
		.replace(/ for action '[a-z_]+'/, "");
	if (rewritten === err.message) return err;
	// ClientSdkActionError carries extra fields — but it is raised by THIS module
	// from a result value, never by the arg validator, so a match here is always
	// a plain ToolUserError. Preserve the httpStatus.
	return new ToolUserError(rewritten, err.httpStatus);
}

export function createActionCaller(
	handler: AdminHandler,
	env: Env,
	ctx: ToolContext,
	/**
	 * Public ClientSDK namespace (e.g. `"feeds"`) this caller belongs to. When
	 * set, arg-validation errors that leak the internal `manage_*` tool name are
	 * rewritten to `client.<namespace>.<method>`. Omit for callers with no public
	 * SDK surface (errors then pass through unchanged).
	 */
	sdkNamespace?: string,
) {
	const manage = <T>(payload: object): Promise<T> =>
		handler(payload as never, env, ctx) as Promise<T>;

	const action = async <T>(
		actionName: string,
		input: object = {},
		/**
		 * Public SDK method name. Defaults to the CAMEL-CASE of the internal
		 * action (`generate_embeddings` → `generateEmbeddings`), which is the
		 * actual method on most namespaces — a bare snake_case default would
		 * render a nonexistent path like `client.classifiers.generate_embeddings`.
		 * Namespaces whose public name diverges from the action (e.g. feeds
		 * `read_feed` → `get`) pass it explicitly.
		 */
		publicMethod: string = snakeToCamel(actionName),
	): Promise<T> => {
		// Spread caller input FIRST, then force `action` so a caller-supplied
		// `action` key (e.g. from a read-only query_sdk script) can never override
		// the discriminator and reach a write/delete handler.
		const { action: _ignored, ...rest } = input as Record<string, unknown>;
		// Rewrite accepted field aliases (sdk-aliases.ts) to their canonical
		// names — the same registry search_sdk renders, so discovery == runtime.
		const canonical = sdkNamespace
			? applyFieldAliases(`${sdkNamespace}.${publicMethod}`, rest)
			: rest;
		let result: T;
		try {
			result = await manage<T>({ ...canonical, action: actionName });
		} catch (err) {
			throw rewriteInternalToolName(err, sdkNamespace, publicMethod);
		}
		const failure = failureMessage(actionName, result);
		if (failure) {
			throw new ClientSdkActionError(
				actionName,
				failure.message,
				failure.result,
			);
		}
		return result;
	};

	return { manage, action };
}
