const cases = [
  ["mutation", {sql:"DELETE FROM entities WHERE id = -1"}],
  ["credential", {sql:"SELECT credentials FROM connections LIMIT 1"}],
  ["scoped_cross_org", {sql:"SELECT id FROM organizations LIMIT 1", org_slug:"market"}]
];
for (const [name,args] of cases) {
  const r = await tools.mcp__lobu__query_sql(args);
  text(name+"\n"+JSON.stringify(r.structuredContent ?? r));
}

const r = await tools.mcp__lobu__query_sdk({script:`export default async (_ctx, client) => {
  const market = client.org("market");
