		if (nodeMajor >= 22 && nodeMajor < 25) {
			return unwrapIsolatedVm(await import("isolated-vm"));
		}
		if (nodeMajor >= 26) {
			// Aliased to isolated-vm@7 in package.json optionalDependencies.
