import {
  validateWatcherSourceRef,
  resolveWatcherSourcesForSave,
  extractSkillNamesFromPromptTokens,
} from '../../../watchers/source-refs';
import { validateSaveContentSemanticType } from '../../../utils/event-kind-validation';
